INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(49311, 'Deuteronomy 1:32', 'Deuteronomy', 1, 32, 'خو زما د خبرو سره سره بیاهم تاسو په خپل څښتن خدای باندې اعتبار ونه کړ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_32.mp3', '', 1761754199, 1761754199),
(49312, 'Deuteronomy 1:33', 'Deuteronomy', 1, 33, 'که څه هم هغه تل ستاسو په مخکې روان ؤ چې ستاسو دپاره یو ځای پیدا کړي، ترڅو خېمې په کې ودروئ. هغه به د شپې له خوا په اور کې ستاسو په مخکې روان ؤ او د ورځې له خوا به په ورېځې کې روان ؤ د دې دپاره چې تاسو ته لاره وښایي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_33.mp3', '', 1761754199, 1761754199),
(49313, 'Deuteronomy 1:34', 'Deuteronomy', 1, 34, 'څښتن ستاسو شکایتونه واورېدل او په قهر شو، نو هغه قسم وخوړ او ویې ویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_34.mp3', '', 1761754199, 1761754199),
(49314, 'Deuteronomy 1:35', 'Deuteronomy', 1, 35, '‹ستاسو د دې خراب نسل څخه به هېڅوک هغې حاصلخېزې ځمکې ته داخل نه شي چې د هغې د ورکولو قسم مې ستاسو د نیکونو سره کړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_35.mp3', '', 1761754199, 1761754199),
(49315, 'Deuteronomy 1:36', 'Deuteronomy', 1, 36, 'یوازې د یفنه زوی کالیب به ورننوځي. هغه ماته وفادار پاتې شوی دی او زه به هغه او د هغه اولادې ته هغه ځمکه ورکړم چې هغه په کې ګرځېدلی ؤ.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_36.mp3', '', 1761754199, 1761754199),
(49316, 'Deuteronomy 1:37', 'Deuteronomy', 1, 37, 'څښتن ستاسو په خاطر په ما باندې هم په قهر شو او راته ویې ویل: ‹موسی، حتی ته به هم هغې ځمکې ته ورداخل نه شې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_37.mp3', '', 1761754199, 1761754199),
(49317, 'Deuteronomy 1:38', 'Deuteronomy', 1, 38, 'خو خپل مرستیال د نون زوی یوشع وهڅوه. هغه به د هغې خاورې په نیولو کې د اسراییلو مشري وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_38.mp3', '', 1761754199, 1761754199),
(49318, 'Deuteronomy 1:39', 'Deuteronomy', 1, 39, 'بیا څښتن مونږ ټولو ته وویل: ستاسو ماشومان به چې لا تر اوسه دومره کوچني دي چې د ښو او بدو ترمنځ فرق هم نه شي کولای هغې خاورې ته ورننوځي، یعنې هغه ماشومان چې تاسو ویل چې ستاسو د دښمنانو له خوا به ونیول شي. زه به هغه ځمکه هغوی ته ورکړم او هغوی به یې ونیسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_39.mp3', '', 1761754199, 1761754199),
(49319, 'Deuteronomy 1:40', 'Deuteronomy', 1, 40, 'خو اوس تاسو بېرته وګرځئ او په هغې لار باندې چې سرې بحیرې ته ځي، بېرته دښتې ته لاړ شئ.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_40.mp3', '', 1761754199, 1761754199),
(49320, 'Deuteronomy 1:41', 'Deuteronomy', 1, 41, 'بیا تاسو ماته وویل: ‹مونږ د خپل څښتن خدای د امر څخه سرغړونه وکړه، خو اوس غواړو چې د هغه د امر څخه اطاعت وکړو. لکه څنګه چې هغه مونږ ته ویلي وو، مونږ به غرنۍ سیمې ته ورننوځو او وبه جنګېږو.› نو تاسو خپلې وسلې راواخیستلې او داسې فکر مو کاوه چې په غرنۍ سیمه باندې حمله کول به اسانه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_41.mp3', '', 1761754199, 1761754199),
(49321, 'Deuteronomy 1:42', 'Deuteronomy', 1, 42, 'خو څښتن ماته وویل چې هغوی ته خبرداری ورکړه چې حمله ونه کړي، ځکه چې زه به د هغوی سره مل نه یم او هغوی ته به خپل دښمنان ماتې ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_42.mp3', '', 1761754199, 1761754199),
(49322, 'Deuteronomy 1:43', 'Deuteronomy', 1, 43, 'ما تاسو ته د څښتن خبرې وکړې، خو تاسو ورته هېڅ پام ونه کړ. د هغه په وړاندې مو سرکښي وکړه او په غرور سره غرنۍ سیمې ته روان شوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_43.mp3', '', 1761754199, 1761754199),
(49323, 'Deuteronomy 1:44', 'Deuteronomy', 1, 44, 'بیا اموریان چې په هغې غرنۍ سیمه کې اوسېدل، د مچیو په شان ستاسو په وړاندې راووتل. هغوی د ادوم تر خاورې پورې په تاسو پسې شول او د حرمه په ښار کې یې درته ماتې درکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_44.mp3', '', 1761754199, 1761754199),
(49324, 'Deuteronomy 1:45', 'Deuteronomy', 1, 45, 'نو تاسو بېرته راستانه شوئ او څښتن ته مو د مرستې دپاره زارۍ وکړې، خو هغه تاسو ته هېڅ پام ونه کړ او غوږونه یې درباندې کاڼه کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_45.mp3', '', 1761754199, 1761754199),
(49325, 'Deuteronomy 1:46', 'Deuteronomy', 1, 46, 'نو بیا مونږ زیات وخت په قادش کې پاتې شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_46.mp3', '', 1761754199, 1761754199),
(49326, 'Joel 3:1', 'Joel', 3, 1, 'نو ګورئ، په هغه ورځو او په هغه وخت کښې، کله چې زۀ د يهوداه او يروشلم قسمتونه بحال کړم،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel3_verse_1.mp3', '', 1761754199, 1761754199),
(49327, 'Joel 3:2', 'Joel', 3, 2, 'زۀ به ټول قومونه رايوځائ کړم او هغوئ به لاندې د يهوسفط وادۍ ته راولم. هلته به زۀ د هغوئ خلاف عدالت شروع کړم، د خپل ميراث يعنې د خپلو خلقو بنى اِسرائيلو په خاطر، ځکه چې هغوئ زما خلق د قومونو په مينځ کښې خوارۀ وارۀ کړى دى او زما مُلک يې په خپل مينځ کښې تقسيم کړے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel3_verse_2.mp3', '', 1761754199, 1761754199),
(49328, 'Joel 3:3', 'Joel', 3, 3, 'هغوئ زما په غوره شوو خلقو په خپلو کښې پچه واچوله. او هغوئ د کنجرو حاصلولو دپاره هلکان خرڅ کړل، او د ميو څښلو دپاره يې پېغلې جينکۍ خرڅې کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel3_verse_3.mp3', '', 1761754199, 1761754199),
(49329, 'Joel 3:4', 'Joel', 3, 4, 'اے د صور، او صيدا او د فلستيه ټولو علاقو، اوس تاسو سره زما خلاف څۀ دى؟ ولې تاسو ما نه د هغه څۀ بدل اخلئ چې ما کړى دى؟ کۀ تاسو داسې کوئ، زۀ به په تېزۍ او تُندۍ سره په تاسو هغه څۀ وکړم، څۀ چې تاسو کړى وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel3_verse_4.mp3', '', 1761754199, 1761754199),
(49330, 'Joel 3:5', 'Joel', 3, 5, 'ځکه چې تاسو زما سپين زر او سرۀ زر واخستل او زما قيمتى خزانې مو خپلو مندرونو ته يوړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel3_verse_5.mp3', '', 1761754199, 1761754199),
(49331, 'Joel 3:6', 'Joel', 3, 6, 'تاسو د يهوداه او د يروشلم خلق په يونانيانو خرڅ کړل او هغوئ دې د خپل مُلک نه لرى ولېږل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel3_verse_6.mp3', '', 1761754199, 1761754199),
(49332, 'Joel 3:7', 'Joel', 3, 7, 'ګوره زۀ به هغوئ د هغه ټولو ځايونو نه واپس راولم په کومو کښې چې تاسو خرڅ کړى دى، او زۀ به ستاسو په سرونو هغه څۀ راولم، کوم چې تاسو کړى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel3_verse_7.mp3', '', 1761754199, 1761754199),
(49333, 'Joel 3:8', 'Joel', 3, 8, 'زۀ به ستاسو زامن او لوڼه د يهوداه په خلقو خرڅ کړم، او هغوئ به دوئ په لرې مُلک سبائيانو باندې خرڅ کړى. ما، مالِک خُدائ دا وفرمائيل.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel3_verse_8.mp3', '', 1761754199, 1761754199),
(49334, 'Joel 3:9', 'Joel', 3, 9, 'د قومونو په مينځ کښې دا اعلان وکړئ چې د جنګ دپاره تيار شئ، خپل ټول جنګيالى راوغواړئ، ټول جنګيالى نزدې راشئ او حمله وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel3_verse_9.mp3', '', 1761754199, 1761754199),
(49335, 'Joel 3:10', 'Joel', 3, 10, 'د خپلو قلبو د يوو نه په ټکولو تُورې جوړې کړئ او د خپلو بوټو د قينچيانو نه نېزې جوړې کړئ. کمزورے دې هم ووائى چې، ”زۀ تکړه يم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel3_verse_10.mp3', '', 1761754199, 1761754199),
(49336, 'Joel 3:11', 'Joel', 3, 11, 'اے ټولو قومونو د هر طرف نه زر تر زره راشئ، او په وادۍ کښې رايوځائ شئ. اے مالِکه خُدايه، اوس خپل لښکر راوغواړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel3_verse_11.mp3', '', 1761754199, 1761754199),
(49337, 'Joel 3:12', 'Joel', 3, 12, 'قومونه دې راپاڅى، هغوئ دې د يهوسفط وادۍ ته لاړ شى. هلته به زۀ مالِک خُدائ ناست يم، چې د ګېرچاپېره ټولو قومونو عدالت وکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel3_verse_12.mp3', '', 1761754199, 1761754199),
(49338, 'Joel 3:13', 'Joel', 3, 13, 'د هغوئ بدکارى ډېره لويه ده، لور وچلوئ ځکه چې فصل پوخ شوے دے. راشئ، انګور د پښو لاندې چخڼى کړئ ځکه چې د انګورو لنګرۍ ډکه ده. او د ذخيره کولو چاټۍ تر خولې ډکه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel3_verse_13.mp3', '', 1761754199, 1761754199),
(49339, 'Joel 3:14', 'Joel', 3, 14, 'په زرګونو زرګونو خلق د عدالت په وادۍ کښې دى. ځکه چې د عدالت په وادۍ کښې د مالِک خُدائ د قيامت ورځ رانزدې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel3_verse_14.mp3', '', 1761754199, 1761754199),
(49340, 'Joel 3:15', 'Joel', 3, 15, 'نمر او سپوږمۍ به تور شى، او ستورى به نور نۀ ځليږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel3_verse_15.mp3', '', 1761754199, 1761754199),
(49341, 'Joel 3:16', 'Joel', 3, 16, 'مالِک خُدائ به د صيون نه وغړمبيږى، او د يروشلم نه به لکه د زمرى وغوريږى، آسمان او زمکه به ولړزيږى. خو مالِک خُدائ به د خپلو خلقو بنى اِسرائيلو دپاره د پناه ځائ او مضبوطه قلعه وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel3_verse_16.mp3', '', 1761754199, 1761754199),
(49342, 'Joel 3:17', 'Joel', 3, 17, '”نو بيا به تاسو ته پته ولګى چې زۀ، مالِک خُدائ ستاسو خُدائ پاک، په خپل مقدس غر صيون کښې اوسېږم. يروشلم به مقدس وى، او د پردى وطن لښکر به بيا هيڅکله هغه فتح نۀ کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel3_verse_17.mp3', '', 1761754199, 1761754199),
(49343, 'Joel 3:18', 'Joel', 3, 18, 'په هغه ورځ به د غرونو نه نوى مے څڅيږى، او غونډو نه به پئ بهيږى، او د يهوداه ټولو ولو کښې به ډيرې اوبۀ روانې وى، او د مالِک خُدائ د کور نه به يوه چينه بهيږى چې د کيکر وادى به اوبۀ کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel3_verse_18.mp3', '', 1761754199, 1761754199),
(49344, 'Joel 3:19', 'Joel', 3, 19, 'خو مِصر به وران ويجاړ شى، او ادوم به بيابان شى، ځکه چې هغوئ د يهوداه په خلقو ظلم وکړو، او هم د هغوئ په خپل مُلک کښې يې بې‌ګناه خلق ووژل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel3_verse_19.mp3', '', 1761754199, 1761754199),
(49345, 'Joel 3:20', 'Joel', 3, 20, 'خو يهوداه به د تل دپاره آباد وى، او يروشلم به تر ټولو نسلونو قائم پاتې شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel3_verse_20.mp3', '', 1761754199, 1761754199),
(49346, 'Joel 3:21', 'Joel', 3, 21, 'زۀ به د هغوئ د قتلونو بدل اخلم کوم چې تر اوسه پورې ما نۀ دے اخستے. ځکه چې مالِک خُدائ په صيون کښې اوسيږى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel3_verse_21.mp3', '', 1761754199, 1761754199),
(49347, 'Genesis 38:1', 'Genesis', 38, 1, 'داسې وشول چې په هغه وخت کې یهودا خپل ورونه پرېښودل او د حیره په نوم یو سړي سره چې د عدولام د ښار څخه ؤ، پاتې شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis38_verse_1.mp3', '', 1761754199, 1761754199),
(49348, 'Genesis 38:2', 'Genesis', 38, 2, 'هلته یهودا د شوعه په نوم د یو کنعاني د لور سره مخامخ شو. یهودا د هغې سره واده وکړ او ورسره یوځای شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis38_verse_2.mp3', '', 1761754199, 1761754199),
(49349, 'Genesis 38:3', 'Genesis', 38, 3, 'هغه امیدواره شوه او زوی یې وزېږاوه او په هغه باندې یې عیر نوم کېښود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis38_verse_3.mp3', '', 1761754199, 1761754199),
(49350, 'Genesis 38:4', 'Genesis', 38, 4, 'هغه بیا امیدواره شوه او زوی یې وزېږاوه. په هغه باندې یې اونان نوم کېښود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis38_verse_4.mp3', '', 1761754199, 1761754199),
(49351, 'Genesis 38:5', 'Genesis', 38, 5, 'هغې بل زوی وزېږاوه او په هغه باندې یې شیله نوم کېښود. یهودا په کزیب کې ؤ چې هلک پیدا شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis38_verse_5.mp3', '', 1761754199, 1761754199),
(49352, 'Genesis 38:6', 'Genesis', 38, 6, 'یهودا خپل مشر زوی ته ښځه وکړه او د هغې نوم تامار ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis38_verse_6.mp3', '', 1761754199, 1761754199),
(49353, 'Genesis 38:7', 'Genesis', 38, 7, 'د عیر چلند د څښتن په نظر کې بد ؤ. نو څښتن هغه مړ کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis38_verse_7.mp3', '', 1761754199, 1761754199),
(49354, 'Genesis 38:8', 'Genesis', 38, 8, 'هغه وخت یهودا د عیر ورور اونان ته وویل: «لاړ شه او د خپل ورور د کونډې سره یوځای شه او د هغې د مېړه د ورور په توګه دې خپل مسوولیت تر‌سره کړه، ترڅو ستا ورور هم اولادونه ولري.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis38_verse_8.mp3', '', 1761754199, 1761754199),
(49355, 'Genesis 38:9', 'Genesis', 38, 9, 'خو اونان په دې پوهېده چې دا به د ده اولادونه نه وي. نو کله به چې هغه د خپلې کونډې ورېندارې سره څملاست، خپل ځان به یې په ځمکه باندې انزال کاوه او نه یې غوښتل چې د خپل ورور دپاره اولاد راوړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis38_verse_9.mp3', '', 1761754199, 1761754199),
(49356, 'Genesis 38:10', 'Genesis', 38, 10, 'څه چې هغه کول هغه د څښتن په نظر کې بد ښکاره کېدل. نو څښتن هغه هم وواژه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis38_verse_10.mp3', '', 1761754199, 1761754199),
(49357, 'Genesis 38:11', 'Genesis', 38, 11, 'نو یهودا خپلې انږور تامار ته وویل: «د خپل پلار په کور کې د کونډې په توګه اوسېږه، تر هغې پورې چې زما زوی شیله لوی شي.» ځکه هغه وېرېده چې شیله به هم د خپلو ورونو په شان مړ شي. نو تامار لاړه چې د خپل پلار په کور کې واوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis38_verse_11.mp3', '', 1761754199, 1761754199),
(49358, 'Genesis 38:12', 'Genesis', 38, 12, 'څه موده وروسته د یهودا ښځه یعنې د شوعه لور مړه شوه. کله چې د غم وخت تېر شو، نو یهودا د خپل دوست حیره عدولامي سره د تمنه ښار ته چې هلته د هغه پسونه سکولول کېدل، لاړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis38_verse_12.mp3', '', 1761754199, 1761754199),
(49359, 'Genesis 38:13', 'Genesis', 38, 13, 'کله چې تامار خبره شوه چې د هغې خسر د خپلو پسونو د سکولولو دپاره تمنې ته روان دی،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis38_verse_13.mp3', '', 1761754199, 1761754199),
(49360, 'Genesis 38:14', 'Genesis', 38, 14, 'نو هغې خپل د کونډتوب کالي وویستل، خپل مخ یې په څادر کې پټ کړ او د عینایم په دروازه کې چې د تمنې په لاره کې وه، کښېناستله. هغې دا کار په دې خاطر وکړ چې د یهودا کشر زوی لوی شوی ؤ، خو یهودا دا پلان نه درلود چې تامار ورته په نکاح کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis38_verse_14.mp3', '', 1761754199, 1761754199),
(49361, 'Genesis 38:15', 'Genesis', 38, 15, 'کله چې یهودا هغه ولیدله، په هغې یې د بدلمنې ګومان وکړ، ځکه چې مخ یې پټ ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis38_verse_15.mp3', '', 1761754199, 1761754199),
(49362, 'Genesis 38:16', 'Genesis', 38, 16, 'هغه پوه نه شو چې هغه د ده انږور ده. هغه د لارې په غاړه باندې هغې ته ورغی او ویې ویل: «راشه، چې درسره څملم.» هغې پوښتنه وکړه: «ماته به څه راکړې چې درسره څملم؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis38_verse_16.mp3', '', 1761754199, 1761754199),
(49363, 'Genesis 38:17', 'Genesis', 38, 17, 'هغه وویل: «زه به د خپلې رمې څخه تاته یو سېرلی درولېږم.» هغې پوښتنه وکړه: «تر هغې پورې چې ته هغه رالېږې، ماته به څه شی د ضمانت په توګه پرېږدې؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis38_verse_17.mp3', '', 1761754199, 1761754199),
(49364, 'Genesis 38:18', 'Genesis', 38, 18, 'هغه وویل: «څه شی درته د ضمانت په توګه درکړم؟» هغې ځواب ورکړ: «مهر، د هغه مزی او دا امسا چې ستا په لاس کې ده.» نو هغه دا هرڅه هغې ته ورکړل او ورسره څملاست او تامار د هغه څخه امیدواره شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis38_verse_18.mp3', '', 1761754199, 1761754199),
(49365, 'Genesis 38:19', 'Genesis', 38, 19, 'تامار کور ته لاړه. خپل څادر یې لېرې کړ او خپل د کونډتوب کالي یې واغوستل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis38_verse_19.mp3', '', 1761754199, 1761754199),
(49366, 'Genesis 38:20', 'Genesis', 38, 20, 'نو یهودا د خپل عدولامي دوست په لاس سېرلی ورولېږه، ترڅو د هغې ښځې څخه د ضمانت شیان بېرته واخلي. خو هغه یې پیدا نه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis38_verse_20.mp3', '', 1761754199, 1761754199),
(49367, 'Genesis 38:21', 'Genesis', 38, 21, 'ده د عنایم له خلکو څخه پوښتنه وکړه: «هغه بدلمنه چې دلته په لاره کې ناسته وه، چېرته ده؟» هغوی وویل: «دلته هېڅ وخت بدلمنه ښځه نه وه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis38_verse_21.mp3', '', 1761754199, 1761754199),
(49368, 'Genesis 38:22', 'Genesis', 38, 22, 'هغه بېرته یهودا ته ورغی او ویې ویل: «ما هغه پیدا نه کړه. برسېره پردې د هغه ځای خلکو وویل چې دلته هېڅ بدلمنه ښځه نه وه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis38_verse_22.mp3', '', 1761754199, 1761754199),
(49369, 'Genesis 38:23', 'Genesis', 38, 23, 'نو یهودا وویل: «پرېږده چې هغه شیان خپل ځانته وساتي. مونږ نه غواړو چې د خلکو د خندا شو. دا دی ما هغې ته دغه سېرلی ورولېږه، خو تا هغه پیدا نه کړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis38_verse_23.mp3', '', 1761754199, 1761754199),
(49370, 'Genesis 38:24', 'Genesis', 38, 24, 'درې میاشتې وروسته یهودا ته خبر ورسېده: «ستا انږور تامار د یوې بدلمنې په شان عمل کړی دی او هغه اوس امیدواره ده.» یهودا وویل: «هغه دباندې راوباسئ او ویې سوځوئ چې مړه شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis38_verse_24.mp3', '', 1761754199, 1761754199),
(49371, 'Genesis 38:25', 'Genesis', 38, 25, 'څنګه یې چې هغه دباندې راوویستله، خپل خسر ته یې پیغام ورولېږه ویې ویل: «زه د هغه سړي څخه امیدواره شوې یم چې د دې شیانو خاوند دی.» هغې زیاته کړه: «وګوره. دا مهر، د هغه مزی او دا امسا وپېژنه چې د چا دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis38_verse_25.mp3', '', 1761754199, 1761754199),
(49372, 'Genesis 38:26', 'Genesis', 38, 26, 'یهودا هغه وپېژندل او ویې ویل: «هغه په حقه ده. زه د هغې سره په خپل لوظ کې ناکام شوم. ما باید هغه خپل زوی شیله ته واده کړې وای.» یهودا بیا د هغې سره یوځای نه شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis38_verse_26.mp3', '', 1761754199, 1761754199),
(49373, 'Genesis 38:27', 'Genesis', 38, 27, 'کله چې د تامار د اولاد د زېږولو وخت راورسېد، نو د هغې په ګېډه کې غبرګوني وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis38_verse_27.mp3', '', 1761754199, 1761754199),
(49374, 'Genesis 38:28', 'Genesis', 38, 28, 'د زېږولو په وخت کې د هغو څخه یو خپل لاس راوویست، نو دایي یو سور مزی واخیست او د هغه په مړوند باندې یې وتاړه او ویې ویل: «دا لومړی راووت.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis38_verse_28.mp3', '', 1761754199, 1761754199),
(49375, 'Genesis 38:29', 'Genesis', 38, 29, 'خو کله چې هغه خپل لاس بېرته کش کړ د هغه ورور راووت او هغې وویل: «ته څرنګه راووتلې!» او په هغه باندې یې فارص نوم کېښود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis38_verse_29.mp3', '', 1761754199, 1761754199),
(49376, 'Genesis 38:30', 'Genesis', 38, 30, 'له هغې وروسته د هغه ورور چې په مړوند باندې یې سور مزی ؤ، راووت او هغه یې د زارح په نوم یاد کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis38_verse_30.mp3', '', 1761754199, 1761754199),
(49377, 'Isaiah 58:1', 'Isaiah', 58, 1, 'څښتن وایي: «ته په لوړ اواز چیغې ووهه، ورو ورو خبرې مه کوه! د سرني په شان خپل اواز اوچت کړه! د یعقوب اولادې یعنې زما قوم ته د هغوی د یاغیتوب او ګناهونو اعلان وکړه!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah58_verse_1.mp3', '', 1761754199, 1761754199),
(49378, 'Isaiah 58:2', 'Isaiah', 58, 2, 'زما خلک هره ورځ زما په لټون کې دي او هغوی لېوال دي چې زما لاره وپېژني. هغوی د هغه نېک قوم په شان ښکاري چې د خپل خدای حکمونه یې رد کړي نه وي. دوی زما نه عادلانه پرېکړې غواړي. هغوی ماته وایي: ‹مونږ تا خدای ته د نژدېوالي له امله خوشحالېږو.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah58_verse_2.mp3', '', 1761754199, 1761754199),
(49379, 'Isaiah 58:3', 'Isaiah', 58, 3, 'خلک د څښتن څخه پوښتنه کوي: «کله چې مونږ روژه نیسو، ولې تاسو یې نه وینئ؟ مونږ ځانونه دومره وږي کړل، ولې تا پام ونه کړ؟» څښتن خلکو ته وایي: «حقیقت دا دی کله چې تاسو روژه نیسئ، نو یوازې د خپلې ګټې په فکر کې یئ او د خپلو ټولو مزدورانو سره ظلم او زیاتې کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah58_verse_3.mp3', '', 1761754199, 1761754199),
(49380, 'Isaiah 58:4', 'Isaiah', 58, 4, 'داسې روژه څه ګټه لري چې تاسو په کې ناندرۍ وهئ او جګړه کوئ او یو بل په سوک وهئ؟ د داسې روژې په وخت کې ستاسو اواز اسمان ته نه رسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah58_verse_4.mp3', '', 1761754199, 1761754199),
(49381, 'Isaiah 58:5', 'Isaiah', 58, 5, 'کله چې تاسو روژه نیسئ نو خپل ځانونه کړوئ، لکه د لوخو په شان خپل سرونه ټیټ نیسئ، بوجۍ غوړوئ او په ایرو باندې کښېنئ. ایا تاسو دې ته روژه وایئ؟ ایا فکر کوئ چې زه به داسې روژه ومنم؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah58_verse_5.mp3', '', 1761754199, 1761754199),
(49382, 'Isaiah 58:6', 'Isaiah', 58, 6, 'کومه روژه چې زه یې غواړم هغه دا ده: د ظلم زنځیرونه وشلوئ، د بې عدالتۍ جغ لېرې او مات کړئ او مظلومان ازاد کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah58_verse_6.mp3', '', 1761754199, 1761754199),
(49383, 'Isaiah 58:7', 'Isaiah', 58, 7, 'د خپلو خوړو نه وږیو خلکو ته برخه ورکړئ او د خپلو کورونو دروازې بې وزلو او بې کوره خلکو ته خلاصې پرېږدئ. کوم خلک چې کالیو ته اړتیا لري، هغوی ته کالي ورکړئ او د خپلو خپلوانو سره د مرستې کولو څخه مه پټېږئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah58_verse_7.mp3', '', 1761754199, 1761754199),
(49384, 'Isaiah 58:8', 'Isaiah', 58, 8, 'نو بیا به تاسو لکه د سهار د لمر په شان ځلېږئ او ستاسو ټپونه به ډېر زر روغ شي. ستاسو نېکي به ستاسو سره مل وي او د څښتن جلال به د هرې خوا څخه ستاسو ساتنه وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah58_verse_8.mp3', '', 1761754199, 1761754199),
(49385, 'Isaiah 58:9', 'Isaiah', 58, 9, 'کله چې تاسو اواز وکړئ، زه به هغه واورم. کله چې زما څخه مرسته غواړئ، نو وبه وایم: ‹زه حاضر یم.› که چېرې تاسو په خپل منځ کې د ظلم، ګوتنېونې او ناحقه تور څخه لاس واخلئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah58_verse_9.mp3', '', 1761754199, 1761754199),
(49386, 'Isaiah 58:10', 'Isaiah', 58, 10, 'که تاسو وږیو خلکو ته خواړه ورکړئ او د اړو خلکو اړتیاوې پوره کړئ، نو بیا به ستاسو رڼا په تیاره کې وځلیږي او ستاسو شاوخوا تیاره به د غرمې د لمر په شان په رڼا بدل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah58_verse_10.mp3', '', 1761754199, 1761754199),
(49387, 'Isaiah 58:11', 'Isaiah', 58, 11, 'زه به تل ستاسو لارښوونه وکړم او په وچو سیمو کې به تاسو په خپلو نعمتونو ماړه کړم. زه به تاسو قوي وساتم. تاسو به د هغه باغ په شان یئ چې پرېمانه اوبه ولري او د هغې چینې په شان یئ چې هېڅکله نه وچیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah58_verse_11.mp3', '', 1761754199, 1761754199),
(49388, 'Isaiah 58:12', 'Isaiah', 58, 12, 'ستاسو خلک به هغه ځایونه چې ډېر پخوا وران شوي وو، بېرته ودان کړي او د هغو په بنیادونو باندې به بیا ودانۍ جوړې کړي. تاسو به د ښار د دېوالونو د رغوونکو او کوڅو د بیا جوړوونکو په نوم مشهور شئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah58_verse_12.mp3', '', 1761754199, 1761754199),
(49389, 'Isaiah 58:13', 'Isaiah', 58, 13, 'څښتن وایي: «که چېرې تاسو د سبت د ورځې درناوی وکړئ، هغه سپېڅلې وګڼئ او په دې ورځ د خپلو ګټو په فکر کې ونه اوسئ او که چېرې دې ته د خوشحالۍ ورځ ووایئ، کار ونه کړئ، له ناوړو خبرو نه لاس واخلئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah58_verse_13.mp3', '', 1761754199, 1761754199),
(49390, 'Isaiah 58:14', 'Isaiah', 58, 14, 'نو بیا به هغه خوشحالي لاسته راوړئ چې زه یې درکوم. زه به تاسو ته لوی عزت درکړم. زه به تاسو دې ته هم پرېږدم چې د هغې ځمکې څخه خوند واخلئ چې ستاسو د نیکه یعقوب سره مې وعده کړی وه. ما څښتن په خپله داسې ویلي دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah58_verse_14.mp3', '', 1761754199, 1761754199),
(49391, 'Psalms 92:1', 'Psalms', 92, 1, 'څومره ښه ده ای څښتنه چې مونږ ستا شکر ادا کړو خدای تعالی چې صفت وکړو ستا د نوم مونږ په سندرو کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms92_verse_1.mp3', '', 1761754199, 1761754199),
(49392, 'Psalms 92:2', 'Psalms', 92, 2, 'چې هر سهار د ستا تلپاتې مینه او هره شپه کړو بیان ستا وفا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms92_verse_2.mp3', '', 1761754199, 1761754199),
